  $$('[data-file]').forEach(el=>el.addEventListener('change',()=>{state.fileMode='custom';const file=files.find(f=>f.id===el.dataset.file);if(el.checked){state.files=state.files.filter(id=>{const f=files.find(x=>x.id===id);return !f||f.cycle!==file.cycle||f.driver!==file.driver||planFamily(f)!==planFamily(file);});state.files.push(file.id);}else state.files=state.files.filter(id=>id!==file.id);update();}));
